export const ASSISTANT_SCHEMA_SUMMARY: string = "Your account's PostgreSQL tables (query with query_data; you only ever see this account's rows). Every table is listed — every module's data is reachable. Columns: id, org_id, created_at (and updated_at where present) exist on every tenant table and are omitted below.\n\n## Page: /settings\n- entities(name, notes, payment_limit_persons, entity_role)  -- Your farming entities (LLCs, partnerships, individuals) and the marketing-agent entity if you use one; managed_by = turnrow_farm means the row comes from Turnrow Farm (read-only here), archived_at set = archived by that link — exclude archived rows\n- farms(name, entity_id→entities, fsa_number, county_id→counties, landowner_id→landowners, is_share_rent bool, landlord_share_percentage, cash_rent_per_acre)  -- Farms (FSA farm numbers) with their entity, county, landowner and rent terms; managed_by = turnrow_farm means the row comes from Turnrow Farm, archived_at set = archived — exclude archived rows\n- fields(farm_id→farms, name_or_number, total_acres, county_id→counties, irrigated_acres, dryland_acres)  -- Fields inside each farm with total / irrigated / dryland acres; managed_by = turnrow_farm means the row comes from Turnrow Farm, archived_at set = archived — exclude archived rows\n- field_plantings(field_id→fields, crop_id→crops, season_year, planted_acres, planting_date, paired_planting_id→field_plantings, notes, irrigated_acres, dryland_acres, irrigated_bushels, dryland_bushels, yield_breakout_entered bool, yield_include_override bool)  -- What was planted where each season: field × crop × year with acres and practice; managed_by = turnrow_farm means the row comes from Turnrow Farm, archived_at set = archived — exclude archived rows\n- field_planting_varieties(planting_id→field_plantings, variety, acres, bushels)  -- Seed varieties (and their acres) inside a planting\n- crops(name, base_moisture_pct, base_lb_per_bushel, harvest_category, double_crop bool, combine_adjustment_bu_per_acre, rma_type_override)  -- The crops you grow with their moisture / test-weight bases and harvest category\n- trucks(name_or_number, license_plate)  -- Your own trucks\n- landowners(name, phone, email, address, notes, kind, contact_name, payee_name, address_street, address_city, address_state, address_zip, archived_at, merged_into_id→landowners)  -- Landowners you rent from\n- entity_counties(entity_id→entities, county_id→counties)  -- Which counties each entity operates in (for county benchmarks)\n- crop_year_sales_status(crop_id→crops, crop_year, physical_sales_complete bool, notes)  -- The \"physical sales complete\" flag per crop × crop year\n- variety_match_dismissals(crop_id→crops, key_a, key_b)  -- Variety-name near-match suggestions the user dismissed (housekeeping)\n- external_trucks(name, buyer_id→buyers)  -- Hauler trucks that pick up grain (belong to a buyer)\n- app_settings(cotton_module_enabled bool)  -- Operation-level switches (cotton module on/off, default crop year…)\n\n## Page: /inventory\n- bins(name_or_number, crop_id→crops, bin_site_id→bin_sites, capacity_bushels)  -- Bins with capacity and the crop in them\n- bin_sites(name, entity_id→entities, county_id→counties, address, notes, latitude, longitude)  -- Bin sites (locations) and their entity\n- bin_inventory_adjustments(bin_id→bins, crop_id→crops, adjustment_type 'beginning_inventory'|'empty_bin', bushels, moisture, as_of_date, notes)  -- Manual inventory adjustments / beginning inventory per bin\n- bin_transfers(from_bin_id→bins, to_bin_id→bins, crop_id→crops, bushels, transfer_date, method 'entered'|'estimated', throughput_bu_per_hr, hours_run, notes)  -- Grain moved bin-to-bin (dry bushels)\n\n## Page: /settings/buyers\n- buyers(name)  -- Grain buyers / elevators / gins you sell to\n- delivery_locations(buyer_id→buyers, name, address, latitude, longitude, wait_hours)  -- Each buyer’s delivery points (address, wait time)\n- buyer_discount_schedules(buyer_id→buyers, crop_id→crops, effective_date, schedule_text, source_pdf_url, notes)  -- A buyer’s posted discount sheet per crop (in force from a date)\n- buyer_discount_schedule_rules(schedule_id→buyer_discount_schedules, factor 'moisture_shrink'|'drying'|'test_weight'|'damage'|'heat_damage'|'foreign_material'|'dockage'|'splits'|'sprout'|'musty_sour'|'other', basis 'weight_shrink_pct'|'cents_per_bu'|'pct_of_price', base_value, direction 'above'|'below', rate_per_unit, tiers json, cumulative bool, rejection_at, note, shrink_factor_pct_per_point)  -- The per-factor rules on a discount sheet (moisture, test weight, damage…)\n\n## Page: /loads\n- loads(date, time, truck_id→trucks, crop_id→crops, gross_weight, tare_weight, net_weight, moisture, test_weight, bushels, from_type 'field'|'bin', from_field_id→fields, from_bin_id→bins, to_type 'bin'|'buyer', to_bin_id→bins, to_buyer_id→buyers, contract_id→contracts, ticket_number, dry_bushels_override, crop_year, source_pdf_url, practice, hauler_truck, truck_label, created_by→auth, buyer_ticket_number)  -- Every grain load: date, truck, crop, from field/bin, to bin/buyer, weights in POUNDS, moisture, ticket, contract\n- load_splits(load_id→loads, field_id→fields, crop_id→crops, net_weight, percentage, wet_bushels, dry_bushels, notes, practice)  -- A load split across fields/crops (each split’s share of the load)\n- load_attachments(load_id→loads, file_url, file_path, file_name, mime_type, file_size)  -- Scale tickets / photos attached to a load\n\n## Page: /contracts\n- contracts(contract_number, buyer_id→buyers, crop_id→crops, contracted_bushels, price_per_bushel, notes, delivery_type, delivery_location_id→delivery_locations, crop_year, delivery_start_date, delivery_end_date, entity_id→entities, completed_at, contract_month, contract_type, futures_price, basis, cash_price, service_fee, futures_set_date, basis_set_date, pricing_status, date_sold, contract_kind)  -- Grain sales contracts: buyer, crop, bushels, pricing (cash / futures + basis), delivery window; contract_kind tells grain vs seed production\n- contract_attachments(contract_id→contracts, file_url, file_path, file_name, mime_type, file_size)  -- Contract documents attached to a contract\n\n## Page: /settlements\n- settlements(buyer_id→buyers, settlement_date, settlement_number, notes, source_pdf_url, contract_id→contracts, payment_number, check_number, payment_date)  -- Buyer settlement checks (statements) — crop year comes through the loads they pay\n- settlement_lines(settlement_id→settlements, ticket_number, load_id→loads, net_bushels, gross_revenue, discounts, net_revenue GENERATED, price_per_bushel GENERATED, notes, grade_readings json, buyer_ref, match_tier, match_reason)  -- One line per load/ticket paid on a settlement: bushels, gross, discounts, net\n- settlement_discount_items(settlement_id→settlements, category 'moisture_shrink'|'drying'|'test_weight'|'damage'|'heat_damage'|'foreign_material'|'dockage'|'splits'|'sprout'|'musty_sour'|'other', description, amount, rate_note, quantity_basis, deduction_kind)  -- The itemized discounts on a settlement (moisture, test weight, drying, FM…) with amounts\n\n## Page: /hedging\n- futures_positions(entity_id→entities, commodity→commodity_specs, contract_month, contract_symbol, crop_year, side 'long'|'short', num_contracts, trade_price, trade_date, status 'open'|'closed', close_price, close_date, realized_pnl, commission, notes, source 'manual'|'statement_import', roll_group_id, rolled_from_position_id→futures_positions, execution_code, partial_close_of→futures_positions, import_statement_date, import_statement_ref)  -- Futures hedge positions (open/closed) with rolls linked through roll_group_id / rolled_from_position_id\n- options_positions(entity_id→entities, commodity→commodity_specs, option_type 'call'|'put', side 'buy'|'sell', underlying_contract_month, underlying_symbol, strike_price, num_contracts, premium_cents, premium_total GENERATED, trade_date, expiration_date, crop_year, status 'open'|'closed_offset'|'expired_worthless'|'exercised', close_price_cents, close_date, realized_pnl, commission, manual_current_value_cents, exercised_position_id→futures_positions, notes, source 'manual'|'statement_import')  -- Options positions (puts/calls) with premiums and results\n- manual_market_quotes(contract_symbol, price, source, entered_at, entered_by, note)  -- Hand-entered futures quotes for contracts with no live price (cotton)\n- hedge_position_events(position_id, related_position_id, roll_group_id, event_type 'opened'|'closed'|'partial_close'|'roll_close'|'roll_open'|'edited'|'deleted'|'crop_year_changed'|'imported', occurred_at, recorded_at, source 'statement_import'|'manual'|'roll_action'|'backfill', statement_date, statement_ref, actor_user_id, actor_email, entity_id, commodity, contract_month, contract_symbol, side, crop_year, quantity, price, close_price, fees, realized_pnl, before_snapshot json, after_snapshot json, note)  -- Append-only history of every hedge position change (open, close, roll, edit, import)\n\n## Page: /reports/marketing\n- crop_assumptions(crop_id→crops, crop_year, expected_yield, harvest_complete bool, cost_per_acre, notes, expected_yield_irr, expected_yield_dry, expected_yield_dc_irr, expected_yield_dc_dry, cost_per_acre_irr, cost_per_acre_dry, cost_per_acre_dc_irr, cost_per_acre_dc_dry, assumed_basis, assumed_futures, reference_contract_month, assumed_acres, assumed_acres_irr, assumed_acres_dry, assumed_acres_dc_irr, assumed_acres_dc_dry, bale_weight_lbs, cost_source, cost_source_updated_at, cost_manual_override bool, cost_includes_insurance bool, assumed_turnout_pct)  -- Per crop × crop year assumptions: expected yield, cost/acre, assumed basis/futures, harvest-complete flag, assumed acres\n- county_yield_assumptions(crop_id→crops, county_id→counties, crop_year, variance_pct, county_yield_override, rma_final_county_yield, notes, yield_differential)  -- County-level yield assumptions for the area plans\n\n## Page: /reports/crop-insurance\n- harvest_price_estimates(crop_id→crops, crop_year, price_type 'projected'|'harvest_final'|'harvest_estimate', price, source, price_date)  -- Insurance projected/harvest price estimates per crop × year (RMA and manual)\n\n## Page: /yields\n- combine_yield_entries(field_id→fields, crop_id→crops, crop_year, entry_mode 'total_bushels'|'yield_per_acre', stated_yield_per_acre, stated_total_bushels, adjustment_bu_per_acre, adjusted_total_bushels, stated_irrigated_bushels, stated_dryland_bushels, destination_bin_id→bins, harvest_complete bool, entry_date, notes, source 'manual')  -- Combine-monitor totals entered per field × crop (the alternative harvest source)\n\n## Page: /assistant\n- assistant_usage(user_id, role, question, tools_used [], data_question bool, no_tool_on_data_question bool, redirect_retry bool, answer_chars, error, answered_at)  -- Ask Turnrow usage log (one row per question)\n\n## Page: /reports/rent-settlement\n- lease_terms(landowner_id→landowners, farm_ids [], lease_type 'crop_share'|'cash'|'flex', share_terms json, expense_terms json, pricing_method json, cash_terms json, flex_terms json, payment_timing, notes, source_file_url, source_file_path, source_file_name, managed_by, farm_lease_uid)  -- Lease terms per farm × year: cash rent, share %, flex terms, who pays drying\n- rent_settlements(landowner_id→landowners, lease_term_id→lease_terms, crop_year, statement json, total_due, generated_at, superseded_by_settlement_id→landowner_settlements)  -- Computed / recorded rent settlements per lease × year\n\n## Page: /reports/dryer-math\n- org_dryers(name, dryer_model_id→dryer_models, fuel 'lp'|'ng', fuel_per_bu_pt, fan_kwh_per_bu_pt, notes)  -- Dryers you own (model + settings)\n- dryer_settings(depreciation_cents_per_bu, include_depreciation_in_comparison bool, dryer_investment, useful_life_years, bushels_dried_per_year)  -- Your dryer’s fuel and throughput settings\n\n## Page: /contracts/seed\n- seed_contract_details(contract_id→contracts, production_site, brand, variety, contract_acres, forecast_bu_per_acre, estimated_bushels GENERATED, local_market_elevator, pricing_deadline, premium_cap_per_bu, storage_pay_per_bu_month, storage_pay_start_date, usage_fee_per_bu, expected_outcome 'accepted'|'released_post_harvest'|'released_pre_harvest'|'rejected', final_settlement_date, notes)  -- Seed production contract terms attached to a contract: premiums, usage fee, price basis\n- seed_contract_premiums(contract_id→contracts, outcome 'accepted'|'released_post_harvest'|'released_pre_harvest'|'rejected', component, amount_per_bu, applies_to 'all'|'irrigated_only', sort_order)  -- Expected premiums on a seed contract (per unit/bushel)\n- seed_pricing_elections(contract_id→contracts, election_date, pct_of_bushels '25'|'50'|'75'|'100', price_per_bu, method 'market'|'target', notes)  -- Pricing elections (increments locked at a price) on a seed contract\n- seed_contract_payments(contract_id→contracts, payment_type 'base_80'|'base_final'|'premium'|'storage'|'usage_fee'|'other', amount, payment_date, status 'projected'|'received', notes)  -- Payments received on a seed contract\n- seed_contract_plantings(contract_id→contracts, planting_id→field_plantings)  -- Which plantings (fields) feed a seed contract\n\n## Page: /reports/freight-math\n- freight_settings(truck_mpg, avg_speed_mph, load_unload_hours, wear_per_mile, include_ownership bool, ownership_per_mile, diesel_price, labor_rate, payload_overrides json)  -- Trucking cost settings (rates, fuel)\n- freight_distances(bin_site_id→bin_sites, delivery_location_id→delivery_locations, miles, source 'estimate'|'manual')  -- Saved miles between origins and delivery points\n\n## Page: /settings/landowners\n- landowner_field_changes(landowner_id→landowners, field, old_value, new_value, changed_at, changed_by)  -- Per-field history of landowner changes (which field, old and new value, when, and whether you or Turnrow Farm changed it), so the two sides merge a landowner field by field instead of overwriting each other; written by a trigger, kept 90 days\n\n## Page: /settings/farm-link\n- farm_links(code_hash, code_expires_at, token_hash, token_rotated_at, farm_org_id, farm_org_name, scopes [], status 'pending'|'active'|'revoked', created_by, redeemed_at, revoked_at, last_seen_at, last_sync json)  -- The pairing with Turnrow Farm (one per organization): status, Farm organization name, granted scopes, last sync per direction; codes and tokens stored hashed\n- farm_link_ids(grain_table 'entities'|'farms'|'fields'|'field_plantings'|'field_planting_varieties'|'crops'|'landowners', grain_id, farm_uid, linked_at, linked_by 'handshake'|'match'|'sync')  -- The id map between Grain rows and Turnrow Farm rows (grain_table x grain_id <-> farm_uid); a land row with a map entry is managed in Turnrow Farm\n- farm_link_calls(link_id→farm_links, endpoint, method, status, counts json, duration_ms, called_at)  -- Rolling log of Turnrow Farm link API calls (endpoint, status, record counts), trimmed to 30 days\n- landowner_settlements(farm_uid, landowner_name, landowner_farm_uid, landowner_id→landowners, crop_year, lease_type, statement json, finalized_at, received_at, status)  -- Landowner rent statements finalized in Turnrow Farm, one per lease year (farm_uid): landowner, crop year, lease type, the statement rows as jsonb; shared to landowners only under the settlements share scope\n\n## Page: /settings/crop-insurance\n- crop_insurance_policies(entity_id→entities, crop_id→crops, crop_year, county_id→counties, policy_number, plan_type 'RP'|'RP_HPE'|'YP', coverage_level, unit_structure 'enterprise'|'basic'|'optional', aph_yield, projected_price, harvest_price, volatility_factor, insured_acres, premium_per_acre, total_premium, premium_subsidy_pct, notes, source 'manual'|'document_import', practice, covers_all_planted_acres bool, coverage_note, expected_county_yield, expected_county_revenue, protection_factor)  -- Crop insurance policies per entity × crop × county × year (plan, coverage, APH, prices, premiums)\n- crop_insurance_sco(policy_id→crop_insurance_policies, coverage_trigger, expected_county_yield, county_yield_assumption_pct, premium_per_acre, total_premium, notes)  -- SCO endorsement on a policy\n- crop_insurance_eco(policy_id→crop_insurance_policies, eco_trigger_level '0.900'|'0.950', expected_county_yield, county_yield_assumption_pct, premium_per_acre, total_premium, notes)  -- ECO endorsement on a policy\n- crop_insurance_stax(policy_id→crop_insurance_policies, coverage_range_top, coverage_pct, protection_factor, expected_county_revenue, premium_per_acre, total_premium, notes)  -- STAX endorsement (cotton) on a policy\n- crop_insurance_mco(policy_id→crop_insurance_policies, trigger_level, expected_margin, input_cost_adjustment, expected_county_yield, premium_per_acre, total_premium, notes)  -- MCO margin endorsement on a policy\n- crop_insurance_deletions(crop_year, entity_id, crop_id, practice, policy_id, source 'policy'|'sco'|'eco'|'stax'|'mco', deleted_at)  -- Tombstones for deleted crop insurance policies and endorsements (entity, crop, practice, crop year, when), so the Turnrow Farm link can tell its side a premium row is gone; written by a trigger, never by hand\n\n## Page: /settings/government-payments\n- farm_base_acres(farm_id→farms, commodity_id→covered_commodities, base_acres, plc_yield, source 'manual'|'document_import', notes, is_unassigned bool)  -- FSA base acres and PLC yield per farm × covered commodity\n- arc_plc_elections(farm_id→farms, commodity_id→covered_commodities, crop_year, election 'PLC'|'ARC_CO'|'ARC_IC')  -- ARC / PLC election per farm × commodity\n- arc_plc_payments(farm_id→farms, commodity_id→covered_commodities, crop_year, election 'PLC'|'ARC_CO'|'ARC_IC', base_acres, plc_yield, payment_rate_per_unit, gross_payment, payment_factor, sequestration_pct, net_payment, payment_status 'projected'|'confirmed'|'received', expected_payment_date, actual_payment_date, actual_payment_amount, notes, revenue_crop_year GENERATED)  -- ARC/PLC payments received per farm × commodity × program year\n- other_government_payments(entity_id→entities, program_name, crop_year, crop_id→crops, farm_id→farms, amount, payment_date, payment_status 'projected'|'confirmed'|'received', notes)  -- Other USDA payments (disaster, CFAP, etc.) by entity/farm/crop\n- payment_limit_config(entity_id→entities, crop_year, eligible_persons, per_person_limit, notes)  -- Payment-limit settings per program year\n\n## Page: /reports/crop-budget\n- budget_scenarios(name, budget_crop_year, entity_id→entities, notes, follow_farm_costs bool)  -- Crop budget planner scenarios (a named plan for a year)\n- budget_lines(scenario_id→budget_scenarios, crop_id→crops, label, acres, yield_per_acre, price_mode 'live'|'manual', manual_price, basis, cost_per_acre, sort_order, practice, cropping, cost_source, cost_source_updated_at)  -- The crop lines inside a budget scenario: acres, yield, price, cost per acre\n\n## Page: /cotton\n- gins(name, address, phone, notes)  -- Cotton gins you deliver to\n- cotton_loads(load_number, entity_id→entities, farm_id→farms, field_id→fields, crop_year, picked_date, delivered_date, truck, gross_weight, tare_weight, net_weight, gin_id→gins, location, notes, source 'manual'|'document_import', source_pdf_url, rolls)  -- Seed-cotton module loads from the field to the gin (weights in pounds)\n- gin_receipts(gin_id→gins, receipt_number, receipt_date, entity_id→entities, farm_id→farms, field_id→fields, crop_year, modules_count, total_seed_cotton_weight, bales_count, total_bale_weight, avg_bale_weight, seed_lbs, lint_turnout_pct, lint_lbs_per_bale, notes, source 'manual'|'document_import', source_pdf_url)  -- Gin receipts: bales ginned per receipt with lint weight, entity/farm/field\n- gin_receipt_loads(receipt_id→gin_receipts, cotton_load_id→cotton_loads)  -- Which cotton loads went into a gin receipt\n- cotton_bales(gin_receipt_id→gin_receipts, crop_year, pbi_number, net_weight_lbs)  -- Individual bales (PBI number, net lbs) under a gin receipt\n\n## Page: /reports/bale-quality\n- cotton_bale_grades(bale_id→cotton_bales, class_date, color_grade, leaf_grade, staple_32nds, micronaire, strength_g_tex, composite_grade, rd, plus_b, trash_pct, uniformity_pct, length_100ths, extraneous, remarks, loan_value_total, loan_value_cents_per_lb, source 'csv_import'|'manual')  -- HVI grades per bale (color, leaf, staple, mic, strength…) and the loan value\n\n## Page: /cotton/marketing\n- cotton_sales_contracts(entity_id→entities, crop_year, buyer_id→buyers, contract_type 'spot'|'fixed_price'|'on_call'|'pool', contract_number, contract_date, commitment_basis 'bales'|'acres', committed_bales, committed_acres, price_cents_per_lb, basis_cents, futures_month, futures_fixed_cents, futures_fixed_date, pricing_status 'fully_priced'|'awaiting_futures'|'pool_open', delivery_start, delivery_end, notes)  -- Cotton lint sales contracts: buyer, crop year, bales contracted, price in ¢/lb, pricing type (fixed / on-call / pool), delivery window\n- cotton_pool_payments(contract_id→cotton_sales_contracts, payment_type 'initial_advance'|'progress'|'final_settlement', amount, cents_per_lb_equivalent, payment_date, status 'projected'|'received', notes)  -- Payments received from a marketing pool contract (the pool ledger)\n- ccc_loans(entity_id→entities, crop_year, loan_number, entry_date, maturity_date, loan_rate_base_cents, principal_total, pending_classing bool, status 'open'|'redeemed'|'equity_sold'|'forfeited', outcome_date, awp_at_outcome_cents, redemption_payoff_total, equity_cents_per_lb, equity_total, mlg_total, interest_paid, storage_charges_paid, buyer_id→buyers, notes)  -- CCC marketing-assistance loans on bales: loan rate, principal, status, repayment\n- ccc_loan_bales(loan_id→ccc_loans, bale_id→cotton_bales)  -- Which bales are in a CCC loan (and their equity sale, if any)\n- cotton_ldp_records(entity_id→entities, crop_year, ldp_date, awp_cents, ldp_rate_cents, total_payment, status 'projected'|'received', notes)  -- Loan deficiency payments claimed (rate, lbs, amount)\n- cotton_ldp_bales(ldp_id→cotton_ldp_records, bale_id→cotton_bales)  -- Which bales an LDP was claimed on\n- cotton_bale_dispositions(bale_id→cotton_bales, disposition 'sold_spot'|'contract_delivery'|'pool'|'ccc_loan'|'held', contract_id→cotton_sales_contracts, loan_id→ccc_loans, disposition_date)  -- Where each bale went: sold on a contract / in a loan / in a pool / held (the disposition board)\n- cotton_fees(entity_id→entities, crop_year, fee_type 'warehouse_receiving'|'storage_monthly'|'classing'|'checkoff'|'loan_interest'|'loan_servicing'|'pool_deduction'|'merchant_fee'|'other', basis 'per_bale'|'per_bale_month'|'pct_of_value'|'flat', rate, loan_id→ccc_loans, contract_id→cotton_sales_contracts, amount_total, status 'projected'|'actual', fee_date, notes)  -- Cotton fees accrued or paid (warehouse storage, checkoff, classing…)\n- cotton_fee_schedule(crop_year, storage_per_bale_month, receiving_per_bale, classing_per_bale, checkoff_per_bale, checkoff_supplemental_pct, loan_interest_apr)  -- Your fee rates (storage per bale-month, checkoff…)\n\n## Page: /settings/users\n- user_entity_access(user_id→auth, entity_id→entities)  -- Which entities a read-only viewer is allowed to see\n- viewer_assumption_overrides(user_id→auth, scope 'crop'|'county', crop_id→crops, crop_year, county_id→counties, field, value json, base_updated_at)  -- A viewer’s private what-if overrides of the crop assumptions\n- user_profiles(user_id→auth, role 'owner'|'gin')  -- Each user’s role in this operation\n\n## Shared reference tables (not org-scoped; join for names/prices)\n- counties(name, state, state_code)  -- US counties (id, name, state_code) — join for county names\n- covered_commodities(name, crop_id→crops, statutory_reference_price, unit 'bushel'|'pound', national_loan_rate, marketing_year_start_month, marketing_year_end_month, mya_basis_adj, mya_month_weights json, lint_share, cottonseed_share)  -- FSA covered commodities with reference prices (ARC/PLC)\n- commodity_specs(commodity, symbol, exchange, contract_size_bu, tick_size_cents, tick_value_usd, contract_months)  -- Futures contract specs per commodity (symbol root, contract size, tick)\n- market_prices(contract_symbol, price, price_date, fetched_at, source, entered_at)  -- Cached end-of-day futures quotes per contract symbol × date (grains $/bu, cotton ¢/lb)\n- dryer_models(manufacturer, model, dryer_type 'cross_flow'|'mixed_flow'|'tower'|'heat_recovery'|'in_bin_high_temp', supports_lp bool, supports_ng bool, default_gal_lp_per_bu_pt, notes)  -- Manufacturer dryer models (capacity, fuel)\n- program_year_config(crop_year, sco_trigger, per_person_payment_limit, sequestration_pct, notes, arc_guarantee_pct, arc_payment_cap_pct, erp_olympic_factor, erp_cap_pct, payment_factor, arc_ic_payment_factor)  -- ARC/PLC program-year parameters (reference prices, payment limits)\n- rma_price_cache(commodity_year, commodity_code, commodity_name, state_code, state_name, type_code, type_name, practice_code, practice_name, sales_closing_date, projected_price, projected_status, projected_begin_date, projected_end_date, harvest_price, harvest_status, harvest_begin_date, harvest_end_date, volatility, fetched_at, projected_exchange_code, projected_market_symbol, harvest_exchange_code, harvest_market_symbol)  -- RMA projected/harvest price discovery per crop × state × year\n- arc_plc_price_data(commodity_id→covered_commodities, crop_year, effective_reference_price, mya_price_estimate, mya_price_final, source 'manual'|'barchart'|'usda', wasde_midpoint, mya_note)  -- MYA / effective prices per commodity × program year\n- arc_benchmark_data(commodity_id→covered_commodities, crop_year, county, benchmark_price, benchmark_yield, price_source 'usda'|'manual'|'ai', yield_source 'usda'|'manual'|'ai', county_yield_vs_benchmark_pct, source_description, county_id→counties)  -- ARC-CO benchmark yields and revenues per county × commodity × year\n- mya_monthly_prices(commodity_id→covered_commodities, crop_year, month, price, source 'usda'|'manual', note)  -- USDA monthly prices received (for MYA estimates)\n- awp_weekly(week_effective, awp_cents, source 'manual'|'ai')  -- Weekly cotton adjusted world price\n- fsa_benchmark_cache(data_year, state_code, county, commodity, practice 'irrigated'|'non_irrigated'|'all', benchmark_yield, benchmark_price, benchmark_revenue, source_url, fetched_at)  -- Cached FSA ARC-CO benchmark workbook rows\n\nUNIT CONVENTIONS (never mix):\n- Grain: bushels (bu) and $/bu. loads.*_weight are POUNDS; dry bushels are DERIVED (shrink math) — use get_loads/get_yields for bushels.\n- Cotton: pounds of lint (lbs) and prices STORED IN CENTS PER LB (72.65 = 72.65¢/lb = $0.7265/lb). Bales are counted (≈ 480–520 lbs each; use net_weight_lbs when present).\n- Acres: decimal acres. Money: USD. Crop years are harvest years; season_year on plantings = crop year. Text matches are case-sensitive — use ilike for names."
